reaction.evaluate:
if (reactorToken.actor.type !== "npc")
    return false;

if (triggerType === "onStructure") {
    if (reactorToken.actor.system.structure.max === 1)
        return false;

    return triggerData.remainingStructure > 0;
}

return true;

reaction.activationCode:
// =============================================================================
// REACTIVE DIALOGUE TEMPLATE
// =============================================================================
//
// MOST USERS ONLY NEED TO EDIT FOUR SECTIONS:
//
//     1. SETTINGS
//     2. NAMED CHARACTER DIALOGUE
//     3. NPC CLASS DIALOGUE
//     4. GENERIC NPC DIALOGUE
//
// The resolver underneath should normally be left alone.
//
// DIALOGUE PRIORITY:
//
// NAMED CHARACTER
//     Exact Action LID
//         ↓
//     Named Character Event
//         ↓
//     SILENCE
//
// NORMAL NPC
//     Exact Class Action LID
//         ↓
//     Class Event
//         ↓
//     Generic NPC Event
//
// IMPORTANT:
//     - Named characters are matched by exact ACTOR NAME.
//     - NPC classes are matched by exact NPC CLASS LID.
//     - Weapons/tech actions are matched by exact item LID.
//     - An explicitly defined empty array [] means intentional silence.
//
// =============================================================================

const communicator = game.modules.get("lancer-communicator")?.api;

if (!communicator) {
    ui.notifications.warn(
        "Reactive Dialogue requires the Lancer Communicator module."
    );
    return;
}

// =============================================================================
// 1. SETTINGS
// =============================================================================

const SETTINGS = {
    // Default communicator presentation style.
    defaultStyle: "red",

    // Automatically used for Structure, Stress, and Destroyed dialogue.
    damagedStyle: "damaged",

    // Communicator notification sound.
    sound: "assets/SFX/Effects/Narrative/Beep.wav",

    // Set true while building profiles to print useful identity information
    // to the browser console.
    debug: false
};

// =============================================================================
// 2. NAMED CHARACTER DIALOGUE
// =============================================================================
//
// Named characters are matched by exact ACTOR NAME.
//
// Named characters are HARD OVERRIDES.
// If they do not have dialogue for the current event, they remain silent.
// They NEVER fall back to class or generic dialogue.
//
// Delete the example below, or duplicate it to create new characters.
//
// AVAILABLE EVENT KEYS:
//
//     onHit
//     onMiss
//     onTechHit
//     onTechMiss
//     onStructure
//     onStress
//     onDestroyed
//
// Exact weapon/tech-action dialogue belongs inside actions:
//
//     actions: {
//         "exact_item_lid": {
//             onHit: ["..."],
//             onMiss: ["..."]
//         }
//     }
//
// Exact-action dialogue overrides the character's normal event dialogue.

const characterDialogue = {

    // -------------------------------------------------------------------------
    // EXAMPLE NAMED CHARACTER
    // -------------------------------------------------------------------------

    "EXAMPLE NAMED CHARACTER": {
        style: "red",

        // Optional.
        // Delete this property to use the token's current artwork instead.
        portrait: "path/to/portrait.png",

        actions: {
            "exact_weapon_lid_here": {
                onHit: [
                    "Example unique weapon hit line.",
                    "Another unique weapon hit line."
                ],

                onMiss: [
                    "Example unique weapon miss line."
                ]
            },

            "exact_tech_action_lid_here": {
                onTechHit: [
                    "Example unique tech success line."
                ],

                onTechMiss: [
                    "Example unique tech failure line."
                ]
            }
        },

        onHit: [
            "Example named-character hit line."
        ],

        onMiss: [
            "Example named-character miss line."
        ],

        onTechHit: [
            "Example named-character tech hit line."
        ],

        onTechMiss: [
            "Example named-character tech miss line."
        ],

        onStructure: [
            "Example named-character Structure line."
        ],

        onStress: [
            "Example named-character Stress line."
        ],

        onDestroyed: [
            "Example named-character destruction line."
        ]
    }
};

// =============================================================================
// 3. NPC CLASS DIALOGUE
// =============================================================================
//
// NPC classes are matched by exact NPC CLASS LID.
//
// Normal NPC priority:
//
//     Exact Action LID
//         ↓
//     Class Event
//         ↓
//     Generic Event
//
// You do NOT need to give every class its own hit/miss dialogue.
// An easy approach is to define only weapons or tech actions that deserve
// unique dialogue, then let everything else fall through to genericDialogue.

const classDialogue = {

    // -------------------------------------------------------------------------
    // EXAMPLE NPC CLASS
    // -------------------------------------------------------------------------

    "npc_class_lid_here": {
        style: "red",

        actions: {
            "exact_weapon_lid_here": {
                onHit: [
                    "Example class-specific weapon hit line."
                ],

                onMiss: [
                    "Example class-specific weapon miss line."
                ]
            },

            "exact_tech_action_lid_here": {
                onTechHit: [
                    "Example class-specific tech success line."
                ],

                onTechMiss: [
                    "Example class-specific tech failure line."
                ]
            }
        },

        // Optional class-wide dialogue.
        // Delete these if you want generic fallback instead.

        onStructure: [
            "Example class-specific Structure line."
        ],

        // Explicit [] means intentional silence for this event.
        onStress: []
    }
};

// =============================================================================
// 4. GENERIC HOSTILE NPC DIALOGUE
// =============================================================================
//
// Used whenever a NORMAL NPC does not have matching class/action dialogue.
// Named characters NEVER fall back here.

const genericDialogue = {
    style: "red",

    onHit: [
        "Hit confirmed.",
        "Target struck.",
        "Good hit.",
        "Contact.",
        "Impact confirmed."
    ],

    onMiss: [
        "Missed. Correcting.",
        "Adjusting fire.",
        "Shot went wide.",
        "No effect. Re-engaging.",
        "Correcting aim."
    ],

    onTechHit: [
        "Connection established.",
        "Target systems compromised.",
        "Got into their systems.",
        "Electronic attack successful.",
        "Access confirmed."
    ],

    onTechMiss: [
        "Connection failed.",
        "They locked me out.",
        "No access.",
        "Electronic attack failed.",
        "Couldn't get through."
    ],

    onStructure: [
        "Armor breach!",
        "Structural damage!",
        "Hull integrity compromised!",
        "I'm hit — still operational!",
        "Damage control!"
    ],

    onStress: [
        "Reactor spike!",
        "Heat critical!",
        "Reactor instability!",
        "Cooling system's struggling!",
        "Temperature warning!"
    ],

    onDestroyed: [
        "I'm hit—!",
        "Systems failing!",
        "I'm going down!",
        "Reactor's gone—!",
        "Unit down!"
    ]
};

// =============================================================================
// RESOLVER
// =============================================================================
//
// YOU SHOULD NOT NORMALLY NEED TO EDIT BELOW THIS LINE.
//
// =============================================================================

// -----------------------------------------------------------------------------
// NPC IDENTITY
// -----------------------------------------------------------------------------

const actorName = reactorToken.actor.name;

const npcClass = reactorToken.actor.items.find(
    candidate => candidate.is_npc_class?.()
);

const classLid = npcClass?.system?.lid;

// -----------------------------------------------------------------------------
// ACTION IDENTIFICATION
// -----------------------------------------------------------------------------
//
// Weapon hits/misses expose triggerData.weapon.
// Tech hits/misses expose triggerData.techItem.

let actionItem;

if (triggerType === "onHit" || triggerType === "onMiss")
    actionItem = triggerData.weapon;
else if (triggerType === "onTechHit" || triggerType === "onTechMiss")
    actionItem = triggerData.techItem;

const actionLid = actionItem?.system?.lid;

if (SETTINGS.debug) {
    console.log(
        "REACTIVE DIALOGUE IDENTITY:",
        "ACTOR:", actorName,
        "CLASS:", classLid ?? "none",
        "ACTION:", actionLid ?? "none",
        "EVENT:", triggerType
    );
}

// -----------------------------------------------------------------------------
// PROFILE EVENT RESOLUTION
// -----------------------------------------------------------------------------

function getProfileEvent(profile) {
    if (!profile)
        return undefined;

    const actionProfile = actionLid
        ? profile.actions?.[actionLid]
        : undefined;

    // Exact action dialogue takes priority.
    // hasOwnProperty is deliberate: [] means intentional silence.
    if (
        actionProfile &&
        Object.prototype.hasOwnProperty.call(
            actionProfile,
            triggerType
        )
    ) {
        return {
            lines: actionProfile[triggerType],
            style: actionProfile.style ?? profile.style,
            portrait: actionProfile.portrait ?? profile.portrait,
            source: "action"
        };
    }

    // Otherwise try the profile-wide event.
    if (
        Object.prototype.hasOwnProperty.call(
            profile,
            triggerType
        )
    ) {
        return {
            lines: profile[triggerType],
            style: profile.style,
            portrait: profile.portrait,
            source: "profile"
        };
    }

    return undefined;
}

// -----------------------------------------------------------------------------
// RESOLVE DIALOGUE SOURCE
// -----------------------------------------------------------------------------

const namedProfile = characterDialogue[actorName];
const classProfile = classDialogue[classLid];

let lines;
let style = SETTINGS.defaultStyle;
let portrait = reactorToken.document.texture.src;
let profileType;

// -----------------------------------------------------------------------------
// NAMED CHARACTER
// -----------------------------------------------------------------------------

if (namedProfile) {
    const result = getProfileEvent(namedProfile);

    // Named characters are hard overrides and never fall through.
    if (!result?.lines?.length) {
        if (SETTINGS.debug) {
            console.log(
                "REACTIVE DIALOGUE: Named character silent/unconfigured",
                actorName,
                triggerType,
                actionLid ?? "none"
            );
        }

        return;
    }

    lines = result.lines;
    style = result.style ?? SETTINGS.defaultStyle;
    portrait = result.portrait ?? reactorToken.document.texture.src;

    profileType = result.source === "action"
        ? "named-action"
        : "named";
}

// -----------------------------------------------------------------------------
// NORMAL NPC
// -----------------------------------------------------------------------------

else {
    const classResult = getProfileEvent(classProfile);

    if (classResult) {
        // Explicit [] = intentional silence.
        if (!classResult.lines?.length)
            return;

        lines = classResult.lines;
        style = classResult.style ?? SETTINGS.defaultStyle;
        portrait = classResult.portrait ?? reactorToken.document.texture.src;

        profileType = classResult.source === "action"
            ? "class-action"
            : "class";
    }

    // Generic fallback.
    else if (genericDialogue[triggerType]?.length) {
        lines = genericDialogue[triggerType];
        style = genericDialogue.style ?? SETTINGS.defaultStyle;
        profileType = "generic";
    }

    else {
        return;
    }
}

// -----------------------------------------------------------------------------
// PICK RANDOM LINE
// -----------------------------------------------------------------------------

const line = lines[Math.floor(Math.random() * lines.length)];

if (SETTINGS.debug) {
    console.log(
        "REACTIVE DIALOGUE:",
        "PROFILE:", profileType,
        "EVENT:", triggerType,
        "ACTION:", actionLid ?? "none",
        "LINE:", line
    );
}

// -----------------------------------------------------------------------------
// COMMUNICATOR PRESENTATION
// -----------------------------------------------------------------------------

if (["onStructure", "onStress", "onDestroyed"].includes(triggerType))
    style = SETTINGS.damagedStyle;

communicator.sendCommunicatorMessage(
    reactorToken.name,
    portrait,
    line,
    SETTINGS.sound,
    "",
    "",
    style
);
